<?php
declare(strict_types=1); require __DIR__.'/../config/config.php'; require_role(['pharmacist','manager','admin']);
function h($v){return htmlspecialchars((string)($v??''),ENT_QUOTES,'UTF-8');}
$pdo=db();$error='';
if($_SERVER['REQUEST_METHOD']==='POST'&&($_POST['action']??'')==='bulk_receive'){
 try{$items=json_decode($_POST['items']??'[]',true)?:[];if(!$items)throw new RuntimeException('Add at least one medicine.');$pdo->beginTransaction();$n=0;
 foreach($items as $x){$mid=(int)($x['medicine_id']??0);$m=$pdo->prepare('SELECT * FROM medicines WHERE id=? AND active=1 FOR UPDATE');$m->execute([$mid]);$med=$m->fetch();if(!$med)throw new RuntimeException('Medicine not found.');$boxes=max(0,(int)($x['boxes']??0));$strips=max(0,(int)($x['strips']??0));$tabs=max(0,(int)($x['tabs']??0));$qty=$boxes*(int)$med['strips_per_box']*(int)$med['units_per_strip']+$strips*(int)$med['units_per_strip']+$tabs;if($qty<1)throw new RuntimeException('Quantity is zero for '.$med['name']);$batch=trim((string)($x['batch']??''))?:null;$expiry=trim((string)($x['expiry']??''))?:null;$cost=max(0,(float)($x['cost']??0));$pdo->prepare('INSERT INTO batches(medicine_id,batch_no,expiry_date,units_received,units_remaining,purchase_unit_cost) VALUES(?,?,?,?,?,?)')->execute([$mid,$batch,$expiry,$qty,$qty,$cost]);$bid=(int)$pdo->lastInsertId();$pdo->prepare("INSERT INTO stock_movements(medicine_id,batch_id,movement_type,quantity_units,note) VALUES(?,?, 'purchase',?,?)")->execute([$mid,$bid,$qty,'Bulk inventory receive']);$n++;}
 $pdo->commit();audit_log('bulk_stock_received',$n.' medicines received');header('Location: inventory_bulk.php?saved='.$n);exit;
 }catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$error=$e->getMessage();}}
$meds=$pdo->query('SELECT id,name,generic_name,units_per_strip,strips_per_box,purchase_price FROM medicines WHERE active=1 ORDER BY name')->fetchAll();
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Bulk Inventory · <?=h(APP_NAME)?></title><link rel="stylesheet" href="style.css"><style>.wrap{overflow:auto}.tbl{min-width:1100px}.tbl input{width:100%;box-sizing:border-box}.picker{position:relative}.results{position:absolute;z-index:20;left:0;right:0;top:100%;background:#fff;border:1px solid #dfe5ef;border-radius:10px;max-height:220px;overflow:auto;box-shadow:0 10px 25px rgba(20,33,61,.15)}.results button{display:block;width:100%;text-align:left;padding:10px;border:0;border-bottom:1px solid #eee;background:#fff;cursor:pointer}.results button:hover{background:#f4f7ff}</style></head><body><header><div class="brand">💊 <?=h(APP_NAME)?></div><nav><a href="index.php">Dashboard</a><a href="pos.php">POS</a><a class="active" href="manage.php">Management</a></nav><div class="user-info">👤 <?=h(current_user()['username']??'')?> · <?=h(ucfirst(current_user()['role']??''))?> · <a href="logout.php">Logout</a></div></header><main><div class="page-title"><div><div class="eyebrow">STOCK CONTROL</div><h1>Bulk Inventory Receive</h1><p>Receive multiple medicines, batches and quantities in one save.</p></div><a class="btn" href="inventory.php">← Inventory</a></div><?php if(isset($_GET['saved'])):?><div class="success">✓ <?=h($_GET['saved'])?> medicine stock lines received.</div><?php endif;?><?php if($error):?><div class="error">✕ <?=h($error)?></div><?php endif;?><section class="panel"><div class="wrap"><table class="tbl" id="tbl"><thead><tr><th>Medicine</th><th>Batch</th><th>Expiry</th><th>Boxes</th><th>Strips</th><th>Loose Tabs</th><th>Cost/Tab</th><th>Total Tabs</th><th></th></tr></thead><tbody></tbody></table></div><div style="display:flex;gap:10px;margin-top:14px"><button type="button" class="btn" id="add">＋ Add Medicine</button><button type="button" class="btn" id="save">💾 Receive All Stock</button></div></section></main><script>const meds=<?=json_encode($meds,JSON_HEX_TAG|JSON_HEX_APOS|JSON_HEX_QUOT|JSON_HEX_AMP)?>;const body=document.querySelector('#tbl tbody');function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));}function addRow(){const tr=document.createElement('tr');tr.innerHTML='<td><div class="picker"><input class="search" placeholder="Search medicine..." autocomplete="off"><input class="id" type="hidden"><div class="results" hidden></div></div></td><td><input class="batch"></td><td><input class="expiry" type="date"></td><td><input class="boxes" type="number" min="0" value="0"></td><td><input class="strips" type="number" min="0" value="0"></td><td><input class="tabs" type="number" min="0" value="0"></td><td><input class="cost" type="number" step="0.0001" min="0" value="0"></td><td class="total">0</td><td><button type="button" class="btn remove">×</button></td>';body.appendChild(tr);const s=tr.querySelector('.search'),r=tr.querySelector('.results'),id=tr.querySelector('.id'),cost=tr.querySelector('.cost');function render(){const q=s.value.trim().toLowerCase();if(!q){r.hidden=true;return}const found=meds.filter(m=>(m.name+' '+(m.generic_name||'')).toLowerCase().includes(q)).slice(0,15);r.innerHTML=found.map(m=>'<button type="button" data-id="'+m.id+'"><b>'+esc(m.name)+'</b><br><small>'+m.units_per_strip+'/strip · '+m.strips_per_box+' strips/box</small></button>').join('')||'<div style="padding:10px">No medicine found.</div>';r.hidden=false;r.querySelectorAll('button').forEach(b=>b.onclick=()=>{const m=meds.find(x=>x.id==b.dataset.id);id.value=m.id;s.value=m.name;cost.value=m.purchase_price||0;r.hidden=true;calc();});}s.addEventListener('input',render);s.addEventListener('focus',render);tr.querySelectorAll('input').forEach(i=>i.addEventListener('input',calc));tr.querySelector('.remove').onclick=()=>{tr.remove();calc();};}function calc(){body.querySelectorAll('tr').forEach(tr=>{const m=meds.find(x=>x.id==tr.querySelector('.id').value);if(!m){tr.querySelector('.total').textContent='0';return}const q=+tr.querySelector('.boxes').value*m.strips_per_box*m.units_per_strip + +tr.querySelector('.strips').value*m.units_per_strip + +tr.querySelector('.tabs').value;tr.querySelector('.total').textContent=q.toLocaleString();});}document.getElementById('add').onclick=addRow;addRow();addRow();document.getElementById('save').onclick=()=>{const items=[...body.querySelectorAll('tr')].map(tr=>({medicine_id:+tr.querySelector('.id').value,batch:tr.querySelector('.batch').value,expiry:tr.querySelector('.expiry').value,boxes:+tr.querySelector('.boxes').value,strips:+tr.querySelector('.strips').value,tabs:+tr.querySelector('.tabs').value,cost:+tr.querySelector('.cost').value})).filter(x=>x.medicine_id);if(!items.length){alert('Add at least one medicine.');return}const f=document.createElement('form');f.method='post';f.action='inventory_bulk.php';f.innerHTML='<input name="action" value="bulk_receive"><input name="items">';f.querySelector('[name=items]').value=JSON.stringify(items);document.body.appendChild(f);f.submit();};document.addEventListener('click',e=>{if(!e.target.closest('.picker'))document.querySelectorAll('.results').forEach(x=>x.hidden=true);});</script></body></html>